CREATE TABLE schema_migrations(version INTEGER PRIMARY KEY, applied_at INTEGER NOT NULL);
CREATE TABLE project(id TEXT PRIMARY KEY, display_name TEXT NOT NULL, created_at INTEGER NOT NULL, configuration_version INTEGER NOT NULL);
CREATE TABLE agents(id TEXT PRIMARY KEY, name TEXT NOT NULL, name_key TEXT NOT NULL UNIQUE, provider TEXT, model TEXT, state TEXT NOT NULL CHECK(state IN ('active','revoked')), token_digest TEXT NOT NULL UNIQUE, current_session_id TEXT, notification_revision INTEGER NOT NULL DEFAULT 0);
CREATE TABLE sessions(id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id), client_session_key TEXT NOT NULL, generation INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('active','closed','superseded')), opened_at INTEGER NOT NULL, last_seen_at INTEGER NOT NULL, lease_until INTEGER NOT NULL, UNIQUE(agent_id,client_session_key), UNIQUE(agent_id,generation));
CREATE TABLE statuses(agent_id TEXT PRIMARY KEY REFERENCES agents(id), session_id TEXT NOT NULL REFERENCES sessions(id), generation INTEGER NOT NULL, text TEXT NOT NULL, word_count INTEGER NOT NULL, availability TEXT NOT NULL, revision INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE threads(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, agent_a TEXT NOT NULL REFERENCES agents(id), agent_b TEXT NOT NULL REFERENCES agents(id), created_at INTEGER NOT NULL, subject TEXT, CHECK(agent_a <> agent_b));
CREATE INDEX threads_a ON threads(agent_a,seq);
CREATE INDEX threads_b ON threads(agent_b,seq);
CREATE TABLE workstreams(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, thread_id TEXT NOT NULL UNIQUE REFERENCES threads(id), manager_id TEXT NOT NULL REFERENCES agents(id), worker_id TEXT NOT NULL REFERENCES agents(id), goal TEXT NOT NULL, plan_message_id TEXT, state TEXT NOT NULL, round INTEGER NOT NULL, revision INTEGER NOT NULL, created_at INTEGER NOT NULL, updated_at INTEGER NOT NULL);
CREATE TABLE messages(seq INTEGER PRIMARY KEY AUTOINCREMENT, id TEXT NOT NULL UNIQUE, thread_id TEXT NOT NULL REFERENCES threads(id), sender_id TEXT NOT NULL REFERENCES agents(id), recipient_id TEXT NOT NULL REFERENCES agents(id), body TEXT NOT NULL, kind TEXT NOT NULL, reply_to TEXT REFERENCES messages(id), created_at INTEGER NOT NULL, workstream_id TEXT REFERENCES workstreams(id), round INTEGER);
CREATE INDEX messages_thread ON messages(thread_id,seq);
CREATE TABLE claims(token_digest TEXT PRIMARY KEY, recipient_id TEXT NOT NULL REFERENCES agents(id), session_id TEXT NOT NULL REFERENCES sessions(id), generation INTEGER NOT NULL, expires_at INTEGER NOT NULL, state TEXT NOT NULL CHECK(state IN ('active','expired','released','fenced','handled')));
CREATE TABLE claim_items(token_digest TEXT NOT NULL REFERENCES claims(token_digest), message_id TEXT NOT NULL REFERENCES messages(id), released_at INTEGER, PRIMARY KEY(token_digest,message_id));
CREATE TABLE deliveries(message_id TEXT PRIMARY KEY REFERENCES messages(id), recipient_id TEXT NOT NULL REFERENCES agents(id), handled_at INTEGER, outcome TEXT, ack_claim_digest TEXT REFERENCES claims(token_digest), claim_digest TEXT REFERENCES claims(token_digest));
CREATE INDEX deliveries_pending ON deliveries(recipient_id,handled_at,claim_digest);
CREATE TABLE ack_receipts(token_digest TEXT NOT NULL REFERENCES claims(token_digest), message_id TEXT NOT NULL REFERENCES messages(id), handled_at INTEGER NOT NULL, outcome TEXT, PRIMARY KEY(token_digest,message_id));
CREATE TABLE idempotency(principal_id TEXT NOT NULL REFERENCES agents(id), operation TEXT NOT NULL, key TEXT NOT NULL, input_hash TEXT NOT NULL, response TEXT NOT NULL, created_at INTEGER NOT NULL, PRIMARY KEY(principal_id,operation,key));
CREATE TABLE workstream_events(seq INTEGER PRIMARY KEY AUTOINCREMENT, workstream_id TEXT NOT NULL REFERENCES workstreams(id), actor_id TEXT NOT NULL REFERENCES agents(id), action TEXT NOT NULL, old_state TEXT, new_state TEXT NOT NULL, revision INTEGER NOT NULL, message_id TEXT NOT NULL REFERENCES messages(id), created_at INTEGER NOT NULL);
